struct AnimationDuration {
    var base: Double = 0.3
    func compute(speed: Double) -> Double {
        base / speed
    }
}

let anim = AnimationDuration()
let result = anim.compute(speed: 2.0)
print("Duration: \(result)")

struct SpringParameters {
    let mass: Double
    let stiffness: Double

    func isStiff() -> Bool {
        stiffness > 100.0
    }
}

let params = SpringParameters(mass: 1.0, stiffness: 180.0)
print("Stiff: \(params.isStiff())")

struct TransitionType {
    let mode: String

    func formatted() -> String {
        "Transition: \(mode.uppercased())"
    }
}

let t = TransitionType(mode: "slide")
