struct ScaleAnimator {
    var scale: Double = 1.0

    mutating func zoom(factor: Double) {
        scale *= factor
    }
}

var animator = ScaleAnimator()
animator.zoom(factor: 1.5)
animator.zoom(factor: 2.0)
print("Scale: \(animator.scale)")

struct RotationTracker {
    var degrees: Double = 45.0

    mutating func rotateQuarter() {
        degrees += 90.0
    }
}

var tracker = RotationTracker()
tracker.rotateQuarter()
print("Angle: \(tracker.degrees)")

struct FadeTransition {
    var opacity: Double = 0.0

    mutating func fadeIn() {
        opacity = 1.0
    }
}

var fade = FadeTransition()
fade.fadeIn()
print("Opacity: \(fade.opacity)")

struct SpringPreset {
    let name: String
    let bounce: Double

    func isBouncy() -> Bool {
        bounce > 0.1
    }
}

let preset = SpringPreset(name: "Snappy", bounce: 0.15)
print("Bouncy: \(preset.isBouncy())")

struct OffsetAnimator {
    var x: Double = 0.0
    var y: Double = 0.0

    mutating func move(dx: Double, dy: Double) {
        x += dx
        y += dy
    }
}

var offset = OffsetAnimator()
offset.move(dx: 10.0, dy: 20.0)
print("Point: \(offset.x),\(offset.y)")

