struct TransitionComposer {
    let hasSlide: Bool
    let hasFade: Bool

    func summary() -> String {
        if hasSlide && hasFade {
            return "Effects: Slide+Fade"
        } else if hasSlide {
            return "Effects: Slide"
        } else if hasFade {
            return "Effects: Fade"
        } else {
            return "Effects: None"
        }
    }
}

func testComposer() {
    let composer = TransitionComposer(hasSlide: true, hasFade: true)
    print(composer.summary())
}

testComposer()

